                const { selectMechanismForDownload } = await import('./fileSaver');
                await Promise.resolve();

                expect(selectMechanismForDownload(MEMORY_DOWNLOAD_LIMIT)).toBe('memory_fallback');
            });
        } finally {
            warning.mockRestore();
        }
    });
});

